# C3 batch c3el (round 30, 2026-10-12) of golf_clean.exe: the modal pilot. Reimplementations in shim/src/re/c3el.cpp;
# fixtures in re/frida/js/fixtures.d/c3el.js (generated by log/c3/alt/c3el_gen_fixture.py from re/frida/js/modal.js and
# log/c3/alt/c3el_fixture_src.js); Purposes and per-jcc branch tables in log/c3/c3el_purpose.md; the modal.js contract in
# log/c3/c3el_notes.txt section 1.
#
# Every key runs under __uiTree (frozen first thread, recording display at 0x0083ad50, heap and import stand-ins, neutral
# window-tree globals). Keys of functions that loop on the pumps also run under __modal: the pumps are stood in on the A/B
# thread by the models in re/frida/js/modal.js, the input arrives as a per-row script, and MODAL_STATE compares the pump
# calls, the script cursor, the virtual clock and every input global.
import os

EXE = "golf_clean.exe"

# re/frida/js/uitree.js: GLOBALS (4 bytes each), the z-list array, the recorder size (as c3ef's registry)
UI_GLOBALS = [0x0083AB94, 0x0083AB90, 0x0083AAE0, 0x0083AAEC, 0x0083AAA0, 0x0083AABC, 0x0083AAC0, 0x0083AAC4, 0x0083AA98,
              0x0083AAF0, 0x0083AB30, 0x0083AB34, 0x0083AB40, 0x0083AB44, 0x0083AB54, 0x0083AC18, 0x00839650, 0x0083AB2C,
              0x0083AA9C, 0x0083A2C8, 0x0083A2CC, 0x0083A2D0, 0x0083A2D4, 0x0083AD50, 0x0083AD4C]
REC_SIZE = 0x1000
ARENA = 0x4000


def UI_STATE(arena=ARENA):
    return ([("$heap", 0, 0x10 + arena), ("$freelog", 0, 0x404), ("$implog", 0, 0x400), ("$rec", 0, REC_SIZE)]
            + [(g, 0, 4) for g in UI_GLOBALS] + [(0x0083A2D8, 0, 0x200)])


# re/frida/js/modal.js: __modal.STATE (the block and the input globals the models and handlers write)
MODAL_STATE = [("$modal", 0, 0x1000), (0x00822B98, 0, 8), (0x00822D58, 0, 0x40), (0x004D3834, 0, 4), (0x0083AD4C, 0, 4),
               (0x0083AFCC, 0, 4), (0x00838208, 0, 4), (0x0083821C, 0, 4), (0x0083AB9C, 0, 4)]

# c3el fixture regions: result sequences, the stood-in callees' and recording objects' call log, the net session globals
FIX_STATE = [("$seq", 0, 16 * 0x48), ("$clog", 0, 0x1000), (0x008400B0, 0, 0x18)]


def _h(addr, fixture, vectors, state, ret="int", args=("int",), abi="default"):
    return dict(module=EXE, addr=addr, abi=abi, ret=ret, args=list(args), fixture=fixture,
                state=UI_STATE() + FIX_STATE + list(state), vectors=vectors)


def _rows(n):
    return [(f"$r{i}",) for i in range(n)]


HOOKS = {}

# ---------------------------------------------------------------------------------------------------- pumpInput483c90 / cf0
for _k in ("", "_n0", "_n1"):
    HOOKS[f"pumpInput483c90{_k}"] = _h(0x00483C90, f"c3el_pi_c90{_k}", _rows(6), [])
    HOOKS[f"pumpInput483cf0{_k}"] = _h(0x00483CF0, f"c3el_pi_cf0{_k}", _rows(6), [])

# ---------------------------------------------------------------------------------------------------- gfxFlushA
HOOKS["gfxFlushA"] = _h(0x00497B00, "c3el_gf", _rows(12), [])

# ---------------------------------------------------------------------------------------------------- Window::runModal
_RM = MODAL_STATE + [(0x0083A4E8, 0, 0x10), (0x0083AA88, 0, 0x10), (0x0083AB50, 0, 4), (0x0083AB58, 0, 4),
                     (0x0083AB38, 0, 4)]
HOOKS["Window::runModal"] = _h(0x0047BAB0, "c3el_rm", [(f"$r{i}", f"$f{i}", f"$p{i}", f"$o{i}") for i in range(14)], _RM,
                               args=("pointer", "int", "pointer", "pointer"), abi="thiscall")

# ---------------------------------------------------------------------------------------------------- runScrollText
_ST = MODAL_STATE + [(0x00838EC0, 0, 0xD8), (0x00839250, 0, 0x48), (0x004E3DA4, 0, 0xC)]
HOOKS["runScrollText"] = _h(0x0046DEA0, "c3el_st", [(f"$r{i}", 1) for i in range(21)], _ST, args=("pointer", "int"))

# ---------------------------------------------------------------------------------------------------- textInputBox
_TI = MODAL_STATE + [(0x0051A068, 0, 0x100)]
HOOKS["textInputBox"] = _h(0x0045B2C0, "c3el_ti", [(f"$r{i}", f"$x{i}", f"$y{i}", f"$m{i}") for i in range(13)], _TI,
                           args=("pointer", "int", "int", "int"))

# ---------------------------------------------------------------------------------------------------- scrollTextWindow
HOOKS["scrollTextWindow"] = _h(0x0046DE70, "c3el_sw", [(f"$r{i}", f"$x{i}", f"$y{i}") for i in range(12)],
                               [(0x00839260, 0, 8), (0x00839278, 0, 4)], args=("pointer", "int", "int"))

# ---------------------------------------------------------------------------------------------------- controls (log/c3/alt only)
# Keys the negative-control runner uses; never registered for the verifier (C3EL_CONTROLS=1 in log/c3/alt/c3el_ctl.py).
if os.environ.get("C3EL_CONTROLS") == "1":
    HOOKS["gfxFlushA_nonet"] = _h(0x00497B00, "c3el_gf_nonet", _rows(12), [])
    HOOKS["Window::runModal_noexit"] = _h(0x0047BAB0, "c3el_rm_noexit", [("$r0", "$f0", "$p0", "$o0")], _RM,
                                          args=("pointer", "int", "pointer", "pointer"), abi="thiscall")
    HOOKS["textInputBox_noexit"] = _h(0x0045B2C0, "c3el_ti_noexit", [("$r0", "$x0", "$y0", "$m0")], _TI,
                                      args=("pointer", "int", "int", "int"))
    HOOKS["runScrollText_noexit"] = _h(0x0046DEA0, "c3el_st_noexit", [("$r0", 1)], _ST, args=("pointer", "int"))
